  ('201', '107', '/uploads/products/jeffries-elite-leather-saddle-01.jpg', 'Seat and cantle in havana brown leather', '1', '0'),
  ('202', '107', '/uploads/products/jeffries-elite-leather-saddle-02.jpg', 'ELITE embossing and hand hole on the flap', '0', '1'),
